    def test_format_recovery_binds_the_immutable_failed_foundry_assignment(self):
        with tempfile.TemporaryDirectory() as path:
            runner = ComposerRunner(self._workflow(Path(path)))
            self.addCleanup(runner.close)
            stage = next(s for s in runner.workflow['stages'] if s['kind']=='experiment')
            work = {'status': 'blocked', 'last_failure_class': 'model_contract',
                'assignment': {'capability_brief': '{"topic": "frozen"}',
                    'configured_input': {'parameters': {'mass_ratio': [100, 200]}}},
                'last_attempt': {'experiment_intent': {'research_question': 'frozen question',
                    'domain': 'plasma', 'parameters': {'dt': .001}},
                    'executor_source': 'original source'},
                'repair_provenance': {'kind': 'independent_repair'}}
            record = runner._publish('command/foundry-work/frozen', 'note', work, 'command.controller')
            context = {'failure_recovery': {'model_diagnostics': {'repair_feedback': {
                'foundry_work_ref': record['artifact_ref'], 'gate': 'review_response_format'}}}}
            order = runner._format_contract_recovery_request(stage, context)
            self.assertEqual(order['foundry_work_ref'], record['artifact_ref'])
            self.assertEqual(order['failure_gate'], 'review_response_format')
            projected = runner._follow_up_projection([order])[0]
            self.assertEqual(projected['foundry_work_ref'], record['artifact_ref'])
            self.assertEqual(projected['failure_gate'], 'review_response_format')
            self.assertEqual(runner._format_recovery_foundry_assignment([order],
                question='frozen question', domain='plasma'), (record['artifact_ref'], work))
            with self.assertRaises(ValidationError):
                runner._format_recovery_foundry_assignment([order],
                    question='foreign question', domain='plasma')
            succeeded = deepcopy(work); succeeded['status']='succeeded'
            other = runner._publish('command/foundry-work/other', 'note', succeeded, 'command.controller')
            with self.assertRaises(ValidationError):
                runner._format_recovery_foundry_assignment([
                    {**order, 'foundry_work_ref': other['artifact_ref']}],
                    question='frozen question', domain='plasma')
            with self.assertRaises(ValidationError):
                runner._format_recovery_foundry_assignment([order,
                    {**order, 'foundry_work_ref': other['artifact_ref']}],
                    question='frozen question', domain='plasma')
            self.assertNotEqual(runner._research_request_signature(order),
                runner._research_request_signature({**order, 'foundry_work_ref': other['artifact_ref']}))

    def test_methods_format_recovery_does_not_inherit_prior_foundry_failure(self):
        with tempfile.TemporaryDirectory() as path:
            runner = ComposerRunner(self._workflow(Path(path)))
            self.addCleanup(runner.close)
            stage = next(s for s in runner.workflow['stages'] if s['kind']=='experiment')
            stale = {'foundry_work_ref': 'artifact:command/foundry-work/prior@1',
                     'gate': 'author_response_format'}
            for diagnostics in ({'repair_gate': 'repair_adjudication_response'}, {}):
                with self.subTest(diagnostics=diagnostics):
                    context = {'repair_feedback': stale,
                        'model_diagnostics': {'repair_feedback': stale},
                        'failure_recovery': {'failure_class': 'model_contract',
                            'model_diagnostics': diagnostics}}
                    order = runner._format_contract_recovery_request(stage, context)
                    self.assertNotIn('foundry_work_ref', order)
                    self.assertNotIn('failure_gate', order)
                    self.assertIsNone(runner._format_recovery_foundry_assignment(
                        [order], question='current question', domain='plasma'))
            context = {'repair_feedback': stale}
            order = runner._format_contract_recovery_request(stage, context,
                dossier={'model_diagnostics': {}})
            self.assertNotIn('foundry_work_ref', order)
            dossier = runner._publish('command/failure/native-response', 'note', {
                'stage_id': stage['id'], 'input_sha256': 'a' * 64,
                'failure_class': 'model_contract',
                'model_diagnostics': {'repair_gate': 'repair_adjudication_response'}
            }, 'command.controller')
            persisted = {**order, 'foundry_work_ref': stale['foundry_work_ref'],
                'failure_dossier_ref': dossier['artifact_ref'],
                'failure_input_sha256': 'a' * 64}
            self.assertIsNone(runner._format_recovery_foundry_assignment(
                [persisted], question='current question', domain='plasma'))
            self.assertEqual(runner.department_activity[-1]['action'],
                             'reconcile_format_recovery_owner')
            with self.assertRaisesRegex(ValidationError, 'bind its response failure dossier'):
                runner._format_recovery_foundry_assignment([
                    {**persisted, 'failure_input_sha256': 'b' * 64}],
                    question='current question', domain='plasma')

    def test_resume_restores_owned_analysis_contract_failure_after_policy_change(self):
        with tempfile.TemporaryDirectory() as path:
            workflow = self._workflow(Path(path))
            runner = ComposerRunner(workflow)
            self.addCleanup(runner.close)
            stage = next(item for item in workflow["stages"] if item.get("kind") == "experiment")
            error = "ModelWorkBlocked: capability foundry did not admit a program: analysis.effect_sizes not_estimable numeric fields must be null"
            dossier = runner._publish("command/composer/failure-recovery/experiment/attempt-55", "report", {
                "stage_id": stage["id"], "attempt_number": 55, "input_sha256": "a" * 64,
                "failure_class": "model_contract", "error": error,
            }, "command.composer")
            latest = {"attempt_number": 55, "state": "failed", "failure_class": "model_contract",
                      "failure_dossier_ref": dossier["artifact_ref"], "error": error}
            runner.stage_records[stage["id"]] = {"kind": "experiment", "status": "blocked",
                "failure_class": "model_contract", "attempt_count": 55, "attempts": [latest], "error": error}
            runner.context[stage["id"]] = {"failure_class": "model_contract", "review_status": "format_recovery_exhausted",
                "failure_dossier_ref": dossier["artifact_ref"], "error": error,
                "format_recovery": True, "format_recovery_dispatched": True,
                "format_recovery_policy_revision": "previous-output-contract-policy",
                "failure_recovery": {"failure_class": "model_contract", "recovery_mode": "format_repair_then_rerun",
                                     "input_sha256": "a" * 64}}
            runner.format_recovery_ledger["previous-policy-signature"] = {"status": "exhausted"}
            by_id = {item["id"]: item for item in workflow["stages"]}
            current_signature = runner._format_recovery_signature(stage, error)
            runner.format_recovery_ledger[current_signature] = {"status": "exhausted"}
            runner.stage_records[stage["id"]]["error"] = "Unchanged experiment input failed 1 time(s): " + error
            with patch.object(runner, "_begin_continuation", return_value=True) as begin:
                self.assertFalse(runner._reopen_blocked_checkpoint(set(), by_id))
                begin.assert_not_called()
            runner.format_recovery_ledger.pop(current_signature)
            with patch.object(runner, "_begin_continuation", return_value=True) as begin:
                self.assertTrue(runner._reopen_blocked_checkpoint(set(), by_id))
                begin.assert_called_once()
            self.assertEqual(runner.context[stage["id"]]["failure_class"], "model_contract")
            self.assertTrue(any(item.get("recovery_mode") == "format_repair_then_rerun"
                                for item in runner.context[stage["id"]]["research_requests"]))
            with patch.object(runner, "_begin_continuation", return_value=True) as begin:
                self.assertFalse(runner._reopen_blocked_checkpoint(set(), by_id))
                begin.assert_not_called()

