    def test_repeated_hold_switches_from_search_expansion_to_topic_refinement(self):
        """A bounded survey repair advances to a scoped refinement, not cloned retries."""
        class FastClock:
            def __init__(self):
                self.value = 0.0

            def __call__(self):
                self.value += 0.05
                return self.value

        with tempfile.TemporaryDirectory() as path:
            root = Path(path)
            workflow = self._workflow(root)
            topic_dir = root / "topic"
            topic_dir.mkdir()
            workflow["stages"].insert(0, {
                "id": "topic", "kind": "topic_discovery",
                "config_path": workflow["stages"][0]["config_path"],
                "project_dir": str(topic_dir.resolve()), "depends_on": [],
                "estimate_seconds": 1, "bindings": [], "deadline_seconds": 5,
                "reuse_completed": False, "reuse_output_path": None,
            })
            for stage in workflow["stages"]:
                stage["deadline_seconds"] = 5
            workflow["stages"][1]["depends_on"] = ["topic"]
            workflow["time_policy"] = {
                "first_result_seconds": 1, "target_seconds": 2,
                "hard_seconds": 5, "checkpoint_seconds": 1,
            }
            workflow["retry_policy"] = {"mode": "until_deadline", "backoff_seconds": 0}
            runner = ComposerRunner(workflow, clock=FastClock())
            calls = []

            def staged(stage, **kwargs):
                calls.append(stage["id"])
                result = {
                    "status": "completed",
                    "output_path": str(Path(stage["project_dir"]) / "result.json"),
                    "project_dir": stage["project_dir"], "stage_id": stage["id"],
                }
                if stage["id"] == "topic":
                    result["topic"] = {
                        "id": "direction_x", "title": "Direction X",
                        "domain": "science", "research_question": "Does X change Y?",
                    }
                elif stage["id"] == "survey":
                    result.update({"gap_state": "insufficient_evidence"})
                    result = runner._gate_free_topic_survey(result, stage=stage)
                return result

            runner._run_stage = staged
            result = runner.run()
            self.assertEqual(result["status"], "research_expansion_required")
            self.assertEqual(result["continuation_cycles"], 2)
            self.assertGreaterEqual(len(calls), 5)
            self.assertEqual(calls[:5], ["topic", "survey", "survey", "topic", "survey"])
            research_decisions = [item for item in result["feedback"]
                                  if item.get("action") == "continue_research"]
            self.assertEqual(len(research_decisions), 2)
            requests = [request for item in research_decisions
                        for request in item.get("research_requests", [])
                        if isinstance(request, dict)]
            self.assertEqual(len({runner._research_request_signature(item)
                                  for item in requests}), len(requests))
            self.assertEqual(result["active_research_requests"], [])
            refinement = next(item for item in requests if item.get("kind") == "topic_refinement")
            self.assertIn("parent phenomenon", refinement["objective"])
            self.assertTrue(any(row.get("request_id") == refinement["id"] and row.get("state") == "completed"
                for activity in result["department_activity"] if activity.get("action") == "resolve_work_orders"
                and activity.get("stage_id") == "topic" for row in activity.get("work_orders", [])))
            current = result["context"]["survey"]
            self.assertEqual(current["status"], "research_expansion_required")
            self.assertEqual(current["gap_state"], "insufficient_evidence")
            self.assertTrue(any(item.get("kind") == "literature_expansion"
                                for item in current.get("research_expansion_requests", [])))
            runner.close()

